import sys

def convert_brute(s, num_rows):
    if num_rows == 1 or num_rows >= len(s):
        return s
    rows = [''] * num_rows
    cur, step = 0, -1
    for ch in s:
        rows[cur] += ch
        if cur == 0 or cur == num_rows - 1:
            step = -step
        cur += step
    return ''.join(rows)

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        sys.exit(0)
    s = lines[0].rstrip()
    num_rows = int(lines[1].strip())
    print(convert_brute(s, num_rows))

import sys

def convert_opt(s, num_rows):
    if num_rows == 1 or num_rows >= len(s):
        return s
    cycle = 2 * (num_rows - 1)
    out = []
    for r in range(num_rows):
        for k in range(r, len(s), cycle):
            out.append(s[k])
            mid = k + cycle - 2 * r
            if r not in (0, num_rows - 1) and mid < len(s):
                out.append(s[mid])
    return ''.join(out)

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        sys.exit(0)
    s = lines[0].rstrip()
    num_rows = int(lines[1].strip())
    print(convert_opt(s, num_rows))

import sys

def convert_best(s, num_rows):
    if num_rows == 1 or num_rows >= len(s):
        return s
    rows = [[] for _ in range(num_rows)]
    cur, step = 0, -1
    for ch in s:
        rows[cur].append(ch)
        if cur == 0 or cur == num_rows - 1:
            step = -step
        cur += step
    return ''.join(''.join(row) for row in rows)

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        sys.exit(0)
    s = lines[0].rstrip()
    num_rows = int(lines[1].strip())
    print(convert_best(s, num_rows))
